per_case_results.actual_sql:
SELECT "player_api_id", "birthday"
FROM "Player"
WHERE SUBSTRING("birthday", 1, 7) = '1970-10';

SELECT (COUNT(CASE WHEN "height" < 180 AND "overall_rating" > 70 THEN 1 END) * 100.0 / COUNT("id")) AS percentage
FROM "player_attributes"
WHERE "height" IS NOT NULL AND "overall_rating" IS NOT NULL;
